void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
class Original:public H8SEmulator {public:int rh()const{return lastread;}int wh()const{return lastwrite;}void histories(int a,int b){lastread=a;lastwrite=b;}int depth()const{return indent;}void depth(int n){indent=n;}};
uint32_t seed=0x2cf41c91;uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
struct Event {uint64_t time;uint32_t pc,sp,at,r0,r1,r6;uint8_t ccr,value;bool write;};
template<class C>struct Bus:H8SDevice {C&c;std::array<Event,128>events{};unsigned n=0;explicit Bus(C&x):c(x){}void record(uint32_t at,uint8_t v,bool w){check(n<events.size(),"bus overflow");events[n++]={c.cycles,uint32_t(c.getPC()),c.getSP(),at,uint32_t(c.reg32(0)),uint32_t(c.reg32(1)),uint32_t(c.reg32(6)),c.ccr,v,w};}uint8_t read(uint32_t at)override{auto v=c.memory[at];record(at,v,false);return v;}void write(uint32_t at,uint8_t v)override{record(at,v,true);c.memory[at]=v;}};
struct F{std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::Stage1Cpu>b=std::make_unique<kstation::Stage1Cpu>();Bus<Original>x{*a};Bus<kstation::Stage1Cpu>y{*b};uint64_t graphs=0,phases=0,events=0,children=0,handlerCalls=0,activityCalls=0;uint32_t stack=0xffff00;
 explicit F(const std::vector<uint8_t>&r){a->loadmem(r.data(),unsigned(r.size()),0);b->loadmem(r.data(),unsigned(r.size()),0);for(auto q:std::array<std::pair<uint32_t,uint32_t>,4>{{{0xc9b6,0x200},{0xfffd20,0x210},{0xffff00,0x80},{0xffffd0,4}}}){a->memmap(&x,q.first,q.second);b->memmap(&y,q.first,q.second);}}
 void byte(uint32_t p,uint8_t v){a->memory[p&0xffffff]=b->memory[p&0xffffff]=v;}void word(uint32_t p,uint16_t v){byte(p,v>>8);byte(p+1,v);}void wide(uint32_t p,uint32_t v){word(p,v>>16);word(p+2,v);}
 void prep(uint32_t pc,uint8_t flags){for(unsigned i=0;i<8;++i)a->regs[i].er=b->regs[i].er=int32_t(rnd());a->pc=a->makepc(pc);b->pc=b->makepc(pc);a->setSP(stack);b->setSP(stack);wide(stack,0x7000);a->ccr=b->ccr=flags;a->exr=b->exr=uint8_t(rnd());a->cycles=b->cycles=rnd();a->histories(0x20000,0x30000);b->histories(0x20000,0x30000);a->depth(2);b->irqDepth(2);a->pending_irqs=b->pending_irqs=0;a->pending_irqs_high=b->pending_irqs_high=0;a->interruptMode2=b->interruptMode2=false;x.n=y.n=0;}
 void equal(){bool ok=a->getPC()==b->getPC()&&a->cycles==b->cycles&&a->ccr==b->ccr&&a->exr==b->exr&&a->getSP()==b->getSP()&&a->rh()==b->readHistory()&&a->wh()==b->writeHistory()&&a->depth()==b->irqDepth();for(unsigned i=0;i<8;++i)ok&=a->regs[i].er==b->regs[i].er;if(!ok){std::fprintf(stderr,"PC=%x/%x cycles=%llu/%llu CCR=%x/%x SP=%x/%x R0=%x/%x R1=%x/%x R6=%x/%x history=%x/%x %x/%x\n",a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->getSP(),b->getSP(),unsigned(a->reg32(0)),unsigned(b->reg32(0)),unsigned(a->reg32(1)),unsigned(b->reg32(1)),unsigned(a->reg32(6)),unsigned(b->reg32(6)),a->rh(),b->readHistory(),a->wh(),b->writeHistory());throw std::runtime_error("frame mismatch");}check(x.n==y.n,"bus count");for(unsigned i=0;i<x.n;++i){auto&p=x.events[i];auto&q=y.events[i];if(!(p.time==q.time&&p.pc==q.pc&&p.sp==q.sp&&p.at==q.at&&p.r0==q.r0&&p.r1==q.r1&&p.r6==q.r6&&p.ccr==q.ccr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"bus at %x/%x, pc %x/%x ccr %x/%x time %llu/%llu\n",p.at,q.at,p.pc,q.pc,p.ccr,q.ccr,p.time,q.time);throw std::runtime_error("bus differs");}}events+=x.n;x.n=y.n=0;for(auto q:std::array<std::pair<uint32_t,uint32_t>,3>{{{0xc9b6,0x200},{0xfffd20,0x210},{0xfffef0,0x20}}})check(!std::memcmp(a->memory+q.first,b->memory+q.first,q.second),"RAM mismatch");}
 void oracle(){a->step();b->step();equal();}
 void queue(kstation::MidiDequeueTask::Kind kind,uint8_t flags,uint16_t consumer,uint16_t producer,uint8_t status,uint8_t data,bool mutate=false){bool e=kind==kstation::MidiDequeueTask::Kind::External;prep(e?0xa02:0x27b6,flags);auto c=e?0xfffd2e:0xc9b8,p=e?0xfffd2c:0xc9b6,base=e?0xfffd30:0xc9ba;word(c,consumer);word(p,producer);byte(0xfffe30,status);byte(base+consumer,data);kstation::NativeMidiDequeue n(kind);unsigned steps=0;while(!n.task().complete()){check(++steps<40,"queue hang");if(mutate&&n.task().stage()==kstation::MidiDequeueTask::Stage::ReadProducer)word(p,uint16_t(consumer+1));check(n.step(*b),"queue rejected");a->step();equal();++phases;}check(unsigned(a->getPC())==0x7000,"queue return");++graphs;}
 void descriptor(uint8_t flags,uint8_t status){prep(0x2a56,flags);a->reg8(8)=b->reg8(8)=int8_t(status);kstation::NativeMidiDescriptor d(status);unsigned steps=0;while(!d.task().complete()){check(++steps<20,"descriptor hang");check(d.step(*b),"descriptor phase");a->step();equal();++phases;}check(uint32_t(a->reg32(0))==d.task().result(),"descriptor result");++graphs;}
 void runUtility(kstation::MidiUtilityTask::Kind kind){kstation::NativeMidiUtility u(kind);unsigned n=0;while(!u.task().complete()){check(++n<20,"utility hang");check(u.step(*b),"utility phase");a->step();equal();++phases;}}
 void utility(kstation::MidiUtilityTask::Kind kind,uint8_t flags,uint8_t port){using K=kstation::MidiUtilityTask::Kind;prep(kind==K::Activity?0x20ba:kind==K::ResetExternal?0x9de:0x279c,flags);byte(0xffffd2,port);byte(0xfffe8f,0xfe);word(0xfffd2c,0xabcd);word(0xfffd2e,0x1234);byte(0xfffe30,0x80);word(0xc9b6,0xabcd);word(0xc9b8,0x1234);byte(0xcaba,0x80);runUtility(kind);check(uint32_t(a->getPC())==0x7000,"utility return");++graphs;}
 void runParser(kstation::MidiParserTask::Kind kind,uint8_t input,bool mutate=false){kstation::NativeMidiParser n(kind,input);unsigned steps=0;using C=kstation::MidiParserTask::Child;
  while(!n.task().complete()){check(++steps<100,"parser hang");if(n.task().awaitingChild()){check(!n.step(*b),"parser wait");auto child=n.task().child();if(child==C::Descriptor){kstation::NativeMidiDescriptor d(uint8_t(a->reg8(8)));while(!d.task().complete()){check(d.step(*b),"parser descriptor");a->step();equal();++phases;}}else if(child==C::Activity){++activityCalls;runUtility(kstation::MidiUtilityTask::Kind::Activity);}else{++handlerCalls;auto at=uint32_t(a->getPC());const uint8_t u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}check(n.resumeChild(*b),"parser resume");++children;continue;}const bool replace=mutate&&n.task().stage()==kstation::MidiParserTask::Stage::ReadHandler;const auto ptr=replace?uint32_t(a->reg32(0))&0xffffff:0;std::array<uint8_t,4>old{};if(replace){for(unsigned i=0;i<4;++i)old[i]=a->memory[ptr+i];wide(ptr,0x9b4);}check(n.step(*b),"parser phase rejected");a->step();equal();if(replace)for(unsigned i=0;i<4;++i)byte(ptr+i,old[i]);++phases;}}
 void parser(kstation::MidiParserTask::Kind kind,uint8_t flags,uint8_t input,uint8_t rem,uint8_t running,uint8_t chan,bool sameChannel,bool mutate=false){bool e=kind==kstation::MidiParserTask::Kind::External;prep(e?0x2954:0x2838,flags);a->reg8(14)=b->reg8(14)=int8_t(input);byte(e?0xcad1:0xcac3,rem);byte(e?0xcacf:0xcac1,running);byte(e?0xcace:0xcac0,chan);wide(e?0xcaca:0xcabc,e?0xcad3:0xcac5);byte(0xbb16,sameChannel?chan:uint8_t(chan+1));runParser(kind,input,mutate);check(uint32_t(a->getPC())==0x7000,"parser return");++graphs;}
 void pump(uint8_t flags,uint8_t status,unsigned extCount,unsigned intCount,bool realistic=false){auto handlersBefore=handlerCalls,activityBefore=activityCalls;prep(0x252c,flags);word(0xfffd2e,0);word(0xfffd2c,extCount);byte(0xfffe30,status);word(0xc9b8,0);word(0xc9b6,intCount);byte(0xcad1,0);byte(0xcac3,0);for(unsigned i=0;i<extCount;++i)byte(0xfffd30+i,uint8_t(0x80+i));for(unsigned i=0;i<intCount;++i)byte(0xc9ba+i,uint8_t(0x20+i));if(realistic){constexpr uint8_t ext[]{0x90,60,127,61,0,0xf8},inner[]{0xb0,1,64,2,65,0xfa};for(unsigned i=0;i<6;++i){byte(0xfffd30+i,ext[i]);byte(0xc9ba+i,inner[i]);}byte(0xbb16,0);}kstation::NativeMidiPump n;unsigned steps=0;
  while(!n.task().complete()){check(++steps<200,"pump hang");if(n.task().awaitingChild()){check(!n.step(*b),"missing wait");const auto child=n.task().child();using C=kstation::MidiPumpTask::Child;
   if(child==C::PopExternal||child==C::PopInternal){kstation::NativeMidiDequeue q(child==C::PopExternal?kstation::MidiDequeueTask::Kind::External:kstation::MidiDequeueTask::Kind::Internal);while(!q.task().complete()){check(q.step(*b),"dequeue phase");a->step();equal();++phases;}}
   else if(child==C::ParseExternal||child==C::ParseInternal){runParser(child==C::ParseExternal?kstation::MidiParserTask::Kind::External:kstation::MidiParserTask::Kind::Internal,uint8_t(a->reg8(14)));}
   else {runUtility(child==C::ResetExternal?kstation::MidiUtilityTask::Kind::ResetExternal:kstation::MidiUtilityTask::Kind::ResetInternal);}
   check(n.resumeChild(*b),"pump resume");++children;continue;}
   check(n.step(*b),"pump phase");a->step();equal();++phases;
  }check(uint32_t(a->getPC())==0x7000,"pump return");if(realistic){check(handlerCalls-handlersBefore==6,"running status event count");check(activityCalls-activityBefore==2,"external activity count");}++graphs;
 }
};
