int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");F f(rom);using K=kstation::MidiDequeueTask::Kind;
 for(auto kind:{kstation::MidiUtilityTask::Kind::ResetExternal,kstation::MidiUtilityTask::Kind::ResetInternal,kstation::MidiUtilityTask::Kind::Activity})for(unsigned flags=0;flags<256;++flags)for(uint8_t port:{uint8_t(0),uint8_t(0x10),uint8_t(0x80),uint8_t(0xff)})f.utility(kind,uint8_t(flags),port);
 for(auto kind:{kstation::MidiParserTask::Kind::External,kstation::MidiParserTask::Kind::Internal})for(unsigned input=0;input<256;++input)for(uint8_t rem:{uint8_t(0),uint8_t(1),uint8_t(2)})for(uint8_t running:{uint8_t(0x90),uint8_t(0xf0),uint8_t(0xf1),uint8_t(0xf8)})for(bool same:{false,true})f.parser(kind,uint8_t(rnd()),uint8_t(input),rem,running,uint8_t(rnd()&15),same);
 for(auto kind:{kstation::MidiParserTask::Kind::External,kstation::MidiParserTask::Kind::Internal})for(unsigned flags=0;flags<256;++flags)for(uint8_t input:{uint8_t(0),uint8_t(0x7f),uint8_t(0x80),uint8_t(0x90),uint8_t(0xc0),uint8_t(0xe0),uint8_t(0xf0),uint8_t(0xf4),uint8_t(0xf8),uint8_t(0xff)})for(uint8_t rem:{uint8_t(0),uint8_t(1),uint8_t(2)})f.parser(kind,uint8_t(flags),input,rem,0x90,2,true,flags%31==0);
 for(unsigned flags=0;flags<256;++flags)for(unsigned status=0;status<256;++status)f.descriptor(uint8_t(flags),uint8_t(status));
 for(auto kind:{K::External,K::Internal})for(unsigned flags=0;flags<256;++flags)for(uint16_t consumer:{uint16_t(0),uint16_t(1),uint16_t(0xff),uint16_t(0x100),uint16_t(0x8000),uint16_t(0xffff)})for(unsigned same=0;same<2;++same)for(uint8_t status:{uint8_t(0),uint8_t(1),uint8_t(2),uint8_t(0x80)})f.queue(kind,uint8_t(flags),consumer,same?consumer:uint16_t(consumer+1),status,uint8_t(rnd()));
 for(auto kind:{K::External,K::Internal})for(unsigned flags=0;flags<256;++flags)f.queue(kind,uint8_t(flags),0xff,0xff,0,0xa4,true);
 {kstation::MidiPumpTask t;check(!t.resume(kstation::MidiPumpTask::Child::PopExternal),"unrequested child");check(t.advance(),"request");check(!t.resume(kstation::MidiPumpTask::Child::PopInternal),"wrong child");check(t.resume(kstation::MidiPumpTask::Child::PopExternal),"expected child");}
 {f.prep(0xa02,0);kstation::NativeMidiDequeue q(K::External);f.b->interruptMode2=true;check(!q.step(*f.b),"interrupt mode guard");f.b->interruptMode2=false;f.b->pending_irqs_high=1;check(!q.step(*f.b),"high irq guard");f.b->pending_irqs_high=0;f.b->pending_irqs=1;check(!q.step(*f.b),"unmasked irq guard");f.b->pending_irqs=0;}
 for(unsigned flags=0;flags<256;++flags)for(uint8_t status:{uint8_t(0),uint8_t(1),uint8_t(2)})for(unsigned e=0;e<3;++e)for(unsigned i=0;i<3;++i)f.pump(uint8_t(flags),status,e,i);
 for(unsigned flags=0;flags<256;++flags)f.pump(uint8_t(flags),0,6,6,true);
 std::printf("{\"passed\":true,\"graphs\":%llu,\"native_phases\":%llu,\"ordered_bus_events\":%llu,\"explicit_children\":%llu}\n",(unsigned long long)f.graphs,(unsigned long long)f.phases,(unsigned long long)f.events,(unsigned long long)f.children);return 0;
}catch(const std::exception&e){std::fprintf(stderr,"FAIL: %s\n",e.what());return 1;}}
